[AUTH role=TECHFLOW_ADMIN]
[GQL-OP roles_merged]
  query {
    contact(id: "@td(MULTI_ORG_TF_BR.id)") {
      id
      rolesInOrganization {
        id
        name
      }
    }
  }
[GQL-EXEC roles_merged]

[AUTH role=TECHFLOW_ADMIN]
[GQL-OP roles_legacy_arg]
  query {
    contact(id: "@td(MULTI_ORG_TF_BR.id)") {
      rolesInOrganization(organizationId: "@td(MULTI_ORG_TF_BR.org_techflow_id)") {
        id
        name
      }
    }
  }
[GQL-EXEC roles_legacy_arg]

