[AUTH role=TECHFLOW_ADMIN]
[GQL-OP contacts_by_role]
  query {
    organization(id: "@td(MULTI_ORG_TF_BR.org_techflow_id)") {
      contacts(first: 20, roleIds: ["org-maintainer"]) {
        totalCount
        items {
          id
          rolesInOrganization { id name }
        }
      }
    }
  }
[GQL-EXEC contacts_by_role]
